import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"3、【屯】 震下坎上","description":"周易口诀义 - 3、【屯】 震下坎上","frontmatter":{"title":"3、【屯】 震下坎上","description":"周易口诀义 - 3、【屯】 震下坎上"},"headers":[],"relativePath":"zh/classics/koujueyi/005.md","filePath":"zh/classics/koujueyi/005.md"}'),r={name:"zh/classics/koujueyi/005.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_3、【屯】-震下坎上" tabindex="-1">3、【屯】 震下坎上 <a class="header-anchor" href="#_3、【屯】-震下坎上" aria-label="Permalink to “3、【屯】 震下坎上”">​</a></h1><p>彖曰：屯，刚柔始交而难生，动乎险中，大亨贞。雷雨之动满盈，天造草昧，宜建侯而不宁。</p><p>象曰：云雷，屯，君子以经纶。</p><p>初九：磐桓，利居贞，利建侯。</p><p>象曰：虽「盘桓」，志行正也。以贵下贱，大得民也。</p><p>六二：屯如邅如，乘马班如，匪寇婚媾。女子贞不字，十年乃字。</p><p>象曰：六二之难，乘刚也。「十年乃字」，反常也。</p><p>六三，即鹿无虞，惟入于林中，君子几不如舍，往吝。</p><p>象曰：「即鹿无虞」，以从禽也。君子舍之，「往吝」穷也。</p><p>六四，乘马班如，求婚媾，往吉，无不利。</p><p>象曰：求而往，明也。</p><p>九五，屯其膏，小贞吉，大贞凶。</p><p>象曰：「屯其膏」，施未光也。</p><p>上六，乘马班如，泣血涟如。</p><p>象曰：「泣血涟如」，何可长也！</p><p>解读</p><p>「屯元亨利贞」者，屯，难也，盈也，天地造始，刚柔始交，动则难生，故曰「难」也。元，大也，以天地始交为难，由难始大通也，故曰「元亨」；因此大通而乃以行贞正，故曰「利贞」也。「勿用有攸往」者，攸，所也，当屯难之时，小人道长，君子道消，若有所往，即为小人侵害，故勿用有所往也。「利建侯」者，处屯难之时，弱求于强，民思其主之时，故利建君侯以为民主。诗云「百姓盈盈，匪君子而不宁」是也。</p><p>象曰「云雷屯，君子以经纶」者，李氏云：「云，阴也；雷，阳也。」阴阳二气相激薄而未通感，情不相得，故难生也。君子处屯难之时，不得安然无事，经营纶理，以辅屯难也。</p><p>初九，磐桓，利居贞，利建侯者，磐桓，是进退不安之貌也。初九以刚阳之德，处群阴之下，即是用谦为体，以贵下贱者也。时未可通，磐桓不安，但以守正而不失其居，故曰「利居贞」也。处难之时，以谦得众，民思其君之时，故利封建君侯，以为民主也。</p><p>「六二，屯如邅如，乘马班如，匪寇婚媾。女子贞不字，十年乃字」者，邅，回也；字，爱也。处屯难之时，强者陵弱，六二是九五之匹，时逢险难，与初相近，情不相得，被初为难，不获前进，故邅回也。「乘马班如」者，班旋不进貌也。二既去五既远，但乘马班旋而不敢前进。「女子贞不字」者，二是五之匹，故执贞奉五，而不受初之字爱也。十年反常，难道乃通，故受五之所爱矣。易之为书，曲畅义理，反明人事，所言「女子不字」，亦犹忠臣遇难，上下暌违，守节不违，其如苏武困于单于，后乃归汉也。</p><p>六三即鹿无虞，惟入于林中，君子几不如舍？「往吝」者，即，就也；虞是掌山泽之官也。六三处屯难之时，阴先求阳，弱者求强，而六三既无正应，往依于五，五又有应在二，而六三若往就五，五所不纳，犹如猎鹿，要假虞官，揆度山川，知鹿所在，既无虞人，徒入于林，终不获鹿。故君子见此，不如弃舍，若强就之，徒劳而已，终至悔吝。故略例云「见情者获，直往即违」是也。</p><p>「六四乘马班如，求婚媾，往吉，无不利」者，六四意就初九，见二与初相近，疑二与初相合，心怀嫌疑，故乘马班旋而不敢进。今六二不从于初，而六四见其情状，可以就往初九，必获媾合，是以往获吉而无不利，言两情相得也。「九五屯其膏，小贞吉，大贞凶」者，九五既处尊位，当屯难之时，固宜拯弱救衰，济民危难，而乃独应于二，即是用心𥚹狭，所济不广，处难以斯，乃非大人弘博之道，即是「小贞吉，大贞凶」也。「膏」，喻恩泽施惠之义。</p><p>「上六：乘马班如，泣血涟如」者，居阴柔之质而无应援，处难之时不能自济，虽复乘马之班旋而无所适，故泣血沲嗟，灭亡在近。说文云：「涟如，泣垂下之貌也。」</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
